1	"use client";
2	
3	import { useLayoutEffect, useRef } from "react";
4	import { useRouter } from "next/navigation";
5	import type { Requirement } from "@/src/lib/api";
6	import { categoryLabel, ConflictBadge, EvidenceBadge, StatusBadge } from "@/src/components/badges";
7	import { ScoreBar } from "@/src/components/ScoreBar";
8	
9	function RankDelta({ oldRank, newRank }: { oldRank?: number; newRank: number }) {
10	  if (!oldRank || oldRank === newRank) return null;
11	  const movedUp = oldRank > newRank;
12	  return (
13	    <span className={`text-xs font-semibold ${movedUp ? "text-emerald-700" : "text-[var(--m-red)]"}`}>
14	      {movedUp ? "▲" : "▼"} {Math.abs(oldRank - newRank)}
15	    </span>
16	  );
17	}
18	
19	// FLIP-Animation (First, Last, Invert, Play): wir merken die Zeilenpositionen vor dem Neuordnen,
20	// verschieben jede Zeile optisch zurück an den alten Platz und lassen sie dann gleiten.
21	// Warum: Der Rangwechsel nach "Apply" ist der beste Demo-Moment, die Jury soll ihn sehen.
22	function useFlip(requirements: Requirement[]) {
23	  const rowRefs = useRef(new Map<string, HTMLTableRowElement>());
24	  const lastTops = useRef(new Map<string, number>());
25	
26	  useLayoutEffect(() => {
27	    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
28	    rowRefs.current.forEach((el, id) => {
29	      const top = el.getBoundingClientRect().top;
30	      const before = lastTops.current.get(id);
31	      if (!reduce && before !== undefined && Math.abs(before - top) > 1) {
32	        el.animate(
33	          [{ transform: `translateY(${before - top}px)` }, { transform: "translateY(0)" }],
34	          { duration: 600, easing: "cubic-bezier(0.22, 1, 0.36, 1)" },
35	        );
36	      }
37	      lastTops.current.set(id, top);
38	    });
39	  }, [requirements]);
40	
41	  return (id: string) => (el: HTMLTableRowElement | null) => {
42	    if (el) rowRefs.current.set(id, el);
43	    else rowRefs.current.delete(id);
44	  };
45	}
46	
47	export function RequirementsTable({
48	  requirements,
49	  previousRanks,
50	  highlightRanks,
51	  conflictTitles,
52	}: {
53	  requirements: Requirement[];
54	  previousRanks: Record<string, number>;
55	  highlightRanks: boolean;
56	  conflictTitles: (r: Requirement) => string[];
57	}) {
58	  const router = useRouter();
59	  const rowRef = useFlip(requirements);
60	  const open = (id: string) => router.push(`/requirements/${id}`);
61	
62	  return (
63	    <div className="overflow-x-auto border-t border-[var(--hairline)]">
64	      <table className="w-full min-w-[900px] text-left text-sm">
65	        <thead className="text-xs uppercase tracking-[0.12em] text-[var(--grey-500)]">
66	          <tr className="border-b border-[var(--hairline)]">
67	            {["Rank", "Title", "Score", "Evidence", "Category", "Status", "Conflict"].map((h) => (
68	              <th key={h} className="px-4 py-3 font-semibold">{h}</th>
69	            ))}
70	          </tr>
71	        </thead>
72	        <tbody>
73	          {requirements.map((req) => {
74	            const conflicts = conflictTitles(req);
75	            const moved = highlightRanks && previousRanks[req.id] !== undefined && previousRanks[req.id] !== req.rank;
76	            return (
77	              <tr
78	                key={req.id}
79	                ref={rowRef(req.id)}
80	                role="link"
81	                tabIndex={0}
82	                onClick={() => open(req.id)}
83	                onKeyDown={(e) => {
84	                  if (e.key === "Enter" || e.key === " ") {
85	                    e.preventDefault();
86	                    open(req.id);
87	                  }
88	                }}
89	                className={`cursor-pointer border-b border-[var(--hairline)] transition-colors hover:bg-[var(--grey-100)] focus:bg-[var(--grey-100)] ${
90	                  moved ? "bg-[#eef4fc]" : "bg-white"
91	                }`}
92	              >
93	                <td className="px-4 py-5">
94	                  <div className="flex items-baseline gap-2">
95	                    <span className="text-3xl font-light tabular-nums text-[var(--ink)]">{req.rank}</span>
96	                    <RankDelta oldRank={previousRanks[req.id]} newRank={req.rank} />
97	                  </div>
98	                </td>
99	                <td className="max-w-sm px-4 py-5">
100	                  <p className="text-base font-light text-[var(--ink)]">{req.title}</p>
101	                  <p className="mt-1 line-clamp-2 text-xs text-[var(--grey-500)]">{req.description}</p>
102	                </td>
103	                <td className="px-4 py-5">
104	                  <ScoreBar score={req.score} source={`${req.signal_ids.length} linked findings`} />
105	                </td>
106	                <td className="px-4 py-5"><EvidenceBadge level={req.evidence_level} reason={req.rationale} /></td>
107	                <td className="px-4 py-5 text-slate-700">{categoryLabel(req.category)}</td>
108	                <td className="px-4 py-5"><StatusBadge status={req.status} /></td>
109	                <td className="px-4 py-5">
110	                  <ConflictBadge
111	                    conflictingTitles={conflicts}
112	                    href={conflicts.length ? `/requirements/${req.id}#signal-${req.signal_ids[0]}` : undefined}
113	                  />
114	                </td>
115	              </tr>
116	            );
117	          })}
118	        </tbody>
119	      </table>
120	    </div>
121	  );
122	}
