1	"use client";
2	
3	import { useState } from "react";
4	import Link from "next/link";
5	import type { Weights } from "@/src/lib/api";
6	import { postLens, type LensResult } from "@/src/lib/insights";
7	import { Button } from "@/src/components/ui/Button";
8	import { EvidenceBadge } from "@/src/components/badges";
9	import { PM_ACTOR, WEIGHT_LABELS } from "./useCockpit";
10	
11	const EXAMPLES = ["Families in the US, focus on charging and space", "What matters most for the 2030 successor?", "Where are we weakest against competitors?"];
12	
13	// Prompt-Linse: Der PM fragt in eigenen Worten. Die KI liefert nur Gewichte und Filter, nie IDs,
14	// Python rechnet die Top 5 auf Kopien. Erst "Apply" schreibt in den Prüfpfad, der PM behält die Kontrolle.
15	export function LensPanel({
16	  scenarioId,
17	  onApply,
18	  applying,
19	}: {
20	  scenarioId: string;
21	  onApply: (weights: Weights, question: string) => void;
22	  applying: boolean;
23	}) {
24	  const [question, setQuestion] = useState("");
25	  const [result, setResult] = useState<LensResult | null>(null);
26	  const [busy, setBusy] = useState(false);
27	  const [error, setError] = useState<string | null>(null);
28	
29	  async function ask(text: string) {
30	    if (!text.trim() || busy) return;
31	    setBusy(true);
32	    setError(null);
33	    try {
34	      setResult(await postLens(scenarioId, text.trim(), PM_ACTOR));
35	    } catch (e) {
36	      setError((e as Error).message);
37	    } finally {
38	      setBusy(false);
39	    }
40	  }
41	
42	  return (
43	    <section className="mb-10 border border-[var(--hairline)] bg-white p-6">
44	      <h2 className="text-xs font-semibold uppercase tracking-[0.16em] text-[var(--grey-500)]">Ask in your own words</h2>
45	      <form
46	        className="mt-4 flex flex-wrap gap-3"
47	        onSubmit={(e) => {
48	          e.preventDefault();
49	          ask(question);
50	        }}
51	      >
52	        <input
53	          value={question}
54	          onChange={(e) => setQuestion(e.target.value)}
55	          placeholder="e.g. Families in the US, focus on charging and space"
56	          aria-label="Question for the prioritization lens"
57	          className="h-[52px] min-w-64 flex-1 border border-[var(--hairline)] px-4"
58	        />
59	        <Button type="submit" disabled={busy}>{busy ? "Thinking..." : "Re-rank"}</Button>
60	      </form>
61	      <div className="mt-3 flex flex-wrap gap-2">
62	        {EXAMPLES.map((ex) => (
63	          <button key={ex} type="button" onClick={() => { setQuestion(ex); ask(ex); }} className="border border-[var(--hairline)] px-3 py-1.5 text-xs hover:border-[var(--ink)]">
64	            {ex}
65	          </button>
66	        ))}
67	      </div>
68	      {error && <p role="alert" className="mt-4 text-sm text-[var(--m-red)]">{error}</p>}
69	      {result && (
70	        <div className="mt-6 border-t border-[var(--hairline)] pt-6">
71	          <p className="text-sm">
72	            <span className="mr-2 border border-[var(--hairline)] px-2 py-0.5 text-xs font-semibold">{result.source === "ai" ? "AI interpretation" : "Rule-based"}</span>
73	            {result.interpretation}
74	          </p>
75	          <p className="mt-2 text-xs text-[var(--grey-500)]">
76	            Suggested weights: {Object.entries(result.weights).map(([k, v]) => `${WEIGHT_LABELS[k as keyof typeof WEIGHT_LABELS] ?? k} ${Number(v).toFixed(2)}`).join(" · ")}
77	          </p>
78	          <ol className="mt-4 grid gap-3">
79	            {result.top.map((t) => (
80	              <li key={t.requirement.id} className="flex flex-wrap items-baseline gap-3 border-t border-[var(--hairline)] pt-3">
81	                <span className="text-2xl font-light tabular-nums">{t.lens_rank}</span>
82	                <Link href={`/requirements/${t.requirement.id}`} className="flex-1 hover:text-[var(--blue)]">{t.requirement.title}</Link>
83	                <EvidenceBadge level={t.requirement.evidence_level} />
84	                <span className="w-full pl-9 text-xs text-[var(--grey-500)]">{t.reasons.map((r) => r.sentence).join(" · ")}</span>
85	              </li>
86	            ))}
87	          </ol>
88	          <p className="mt-4 text-xs text-[var(--grey-500)]">Nothing is stored yet. Apply these weights to re-rank the list and record your rationale.</p>
89	          <div className="mt-3">
90	            <Button disabled={applying} onClick={() => onApply(result.weights, result.question)}>Apply these weights</Button>
91	          </div>
92	        </div>
93	      )}
94	    </section>
95	  );
96	}
