1	"use client";
2	
3	import { useCallback, useEffect, useMemo, useState } from "react";
4	import {
5	  getRequirements,
6	  getScenarios,
7	  getSignals,
8	  putWeights,
9	  type Requirement,
10	  type Scenario,
11	  type Signal,
12	  type WeightKey,
13	  type Weights,
14	} from "@/src/lib/api";
15	import { DEFAULT_SCENARIO_ID } from "@/src/components/shell/scenarioLabel";
16	
17	// State und API-Aufrufe des Cockpits, unverändert aus der alten app/page.tsx übernommen.
18	// Warum ausgelagert: die Seite bleibt unter 200 Zeilen und die Logik ist getrennt vom Aussehen testbar.
19	export const PM_ACTOR = "pm.demo";
20	export const DEFAULT_WEIGHTS: Record<WeightKey, number> = {
21	  customer_pain: 0.25,
22	  reach: 0.2,
23	  satisfaction_gap: 0.2,
24	  competitive_pressure: 0.15,
25	  future_relevance: 0.1,
26	  effort_inverse: 0.1,
27	};
28	export const WEIGHT_LABELS: Record<WeightKey, string> = {
29	  customer_pain: "Customer pain",
30	  reach: "Reach",
31	  satisfaction_gap: "Satisfaction gap",
32	  competitive_pressure: "Competitive pressure",
33	  future_relevance: "Future relevance",
34	  effort_inverse: "Low effort",
35	};
36	export const DEMO_RATIONALE = "Demo adjustment: product management is testing a different prioritization focus.";
37	
38	function weightsFromRequirements(requirements: Requirement[]): Record<WeightKey, number> {
39	  const first = requirements[0]?.score_breakdown;
40	  const out = { ...DEFAULT_WEIGHTS };
41	  (Object.keys(out) as WeightKey[]).forEach((key) => {
42	    out[key] = first?.[key]?.weight ?? DEFAULT_WEIGHTS[key];
43	  });
44	  return out;
45	}
46	
47	export function useCockpit(initialScenarioId: string | null) {
48	  const [scenarios, setScenarios] = useState<Scenario[]>([]);
49	  // Das Szenario kommt aus der URL (?scenario=, Deep-Link). Ist es unbekannt, nehmen wir das erste vorhandene.
50	  const [fallbackId, setFallbackId] = useState<string | null>(null);
51	  const scenarioId = initialScenarioId ?? fallbackId ?? DEFAULT_SCENARIO_ID;
52	  const [loadedFor, setLoadedFor] = useState<string | null>(null);
53	  const [requirements, setRequirements] = useState<Requirement[]>([]);
54	  const [signals, setSignals] = useState<Signal[]>([]);
55	  const [weights, setWeights] = useState<Record<WeightKey, number>>(DEFAULT_WEIGHTS);
56	  const [rationale, setRationale] = useState("");
57	  const [previousRanks, setPreviousRanks] = useState<Record<string, number>>({});
58	  const [highlightRanks, setHighlightRanks] = useState(false);
59	  const [applying, setApplying] = useState(false);
60	  const [error, setError] = useState<string | null>(null);
61	  const [toast, setToast] = useState<string | null>(null);
62	
63	  useEffect(() => {
64	    getScenarios()
65	      .then((loaded) => {
66	        setScenarios(loaded);
67	        if (!loaded.some((s) => s.id === scenarioId) && loaded[0]) setFallbackId(loaded[0].id);
68	      })
69	      .catch((err: Error) => setError(err.message));
70	    // eslint-disable-next-line react-hooks/exhaustive-deps
71	  }, []);
72	
73	  useEffect(() => {
74	    let cancelled = false;
75	    Promise.all([getRequirements(scenarioId), getSignals(scenarioId)])
76	      .then(([nextRequirements, nextSignals]) => {
77	        if (cancelled) return;
78	        setRequirements(nextRequirements);
79	        setSignals(nextSignals);
80	        setWeights(weightsFromRequirements(nextRequirements));
81	        setPreviousRanks({});
82	        setError(null);
83	      })
84	      .catch((err: Error) => {
85	        if (!cancelled) setError(err.message);
86	      })
87	      .finally(() => {
88	        if (!cancelled) setLoadedFor(scenarioId);
89	      });
90	    return () => {
91	      cancelled = true;
92	    };
93	  }, [scenarioId]);
94	
95	  const loading = loadedFor !== scenarioId;
96	  const signalById = useMemo(() => new Map(signals.map((s) => [s.id, s])), [signals]);
97	  const selectedScenario = scenarios.find((s) => s.id === scenarioId);
98	
99	  const conflictTitles = useCallback(
100	    (requirement: Requirement) =>
101	      requirement.signal_ids.flatMap((id) =>
102	        (signalById.get(id)?.conflicts_with ?? []).map((cid) => signalById.get(cid)?.title ?? cid),
103	      ),
104	    [signalById],
105	  );
106	
107	  async function applyWeights(nextWeights: Weights = weights, why?: string) {
108	    if (applying) return;
109	    setApplying(true);
110	    setError(null);
111	    const before = Object.fromEntries(requirements.map((req) => [req.id, req.rank]));
112	    try {
113	      const reranked = await putWeights(scenarioId, {
114	        weights: nextWeights,
115	        actor: PM_ACTOR,
116	        rationale: (why ?? rationale).trim() || DEMO_RATIONALE,
117	      });
118	      setPreviousRanks(before);
119	      setRequirements(reranked);
120	      setWeights(weightsFromRequirements(reranked));
121	      setRationale("");
122	      setHighlightRanks(true);
123	      setToast("WEIGHTS_CHANGED recorded");
124	      window.setTimeout(() => setHighlightRanks(false), 2500);
