12	// Leichter Parallax ohne GSAP: Das Hintergrundbild wandert langsamer als die Seite.
13	function useParallax() {
14	  const ref = useRef<HTMLDivElement>(null);
15	  useEffect(() => {
16	    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
17	    const el = ref.current;
18	    if (!el?.parentElement) return;
19	    const parent = el.parentElement;
20	    let raf = 0;
21	    const onScroll = () => {
22	      cancelAnimationFrame(raf);
23	      raf = requestAnimationFrame(() => {
24	        const r = parent.getBoundingClientRect();
25	        el.style.transform = `translateY(${(r.top / window.innerHeight) * -60}px)`;
26	      });
27	    };
28	    onScroll();
29	    window.addEventListener("scroll", onScroll, { passive: true });
30	    return () => {
31	      window.removeEventListener("scroll", onScroll);
32	      cancelAnimationFrame(raf);
33	    };
34	  }, []);
35	  return ref;
36	}
